function avatarUrlFor(user) {
  if (!user) return null;
  if (!user.avatar_data && !user.avatar_version) return null;
  return `/avatar/${user.id}?v=${user.avatar_version || 0}`;
}

async function handleAvatarUpload(request, env, user) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungueltige Anfrage." }, 400);
  }
  const avatar = body.avatar;
  if (typeof avatar !== "string" || !avatar.startsWith("data:image/")) {
    return json({ error: "Ungueltiges Bildformat." }, 400);
  }
  if (avatar.length > 400000) {
    return json({ error: "Bild ist zu gross." }, 413);
  }
  const match = avatar.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return json({ error: "Ungueltiges Bildformat." }, 400);
  const mime = match[1];
  const bytes = Uint8Array.from(atob(match[2]), (c) => c.charCodeAt(0));
  await env.FILES_BUCKET.put(`avatars/${user.id}`, bytes, { httpMetadata: { contentType: mime } });
  await env.DB.prepare(
    "UPDATE users SET avatar_data = NULL, avatar_version = avatar_version + 1, updated_at = datetime('now') WHERE id = ?1"
  )
    .bind(user.id)
    .run();
  await logActivity(env, user, "avatar_change", null);
  return json({ ok: true });
}

async function handleAvatarDelete(env, user) {
  try {
    await env.FILES_BUCKET.delete(`avatars/${user.id}`);
  } catch {
    // Objekt evtl. gar nicht vorhanden -- kein Problem.
  }
  await env.DB.prepare(
    "UPDATE users SET avatar_data = NULL, avatar_version = 0, updated_at = datetime('now') WHERE id = ?1"
  )
    .bind(user.id)
    .run();
  await logActivity(env, user, "avatar_delete", null);
  return json({ ok: true });
}

async function handleDeleteAccount(request, env, user) {
  let body;
  try {
    body = await request.json();
  } catch {
    body = {};
  }
  if (body.confirm !== "LÖSCHEN") {
    return json({ error: "Bestätigung fehlt oder ist ungültig." }, 400);
  }
  const userName = `${user.vorname} ${user.nachname}`;

  // Zuweisungen aufloesen, damit keine verwaisten Referenzen in Tickets bleiben --
  // Aufgaben/Tickets selbst bleiben erhalten (dort stehen Namen ohnehin als Text-Snapshot).
  await env.DB.prepare("UPDATE tickets SET assigned_to = NULL WHERE assigned_to = ?1").bind(user.id).run();
  await env.DB.prepare("UPDATE ticket_messages SET author_id = NULL WHERE author_id = ?1").bind(user.id).run();
  await env.DB.prepare("DELETE FROM password_resets WHERE user_id = ?1").bind(user.id).run();
  await env.DB.prepare("DELETE FROM sessions WHERE user_id = ?1").bind(user.id).run();
  try {
    await env.FILES_BUCKET.delete(`avatars/${user.id}`);
  } catch {
    // kein Avatar vorhanden -- kein Problem.
  }
  await env.DB.prepare("DELETE FROM users WHERE id = ?1").bind(user.id).run();

  await logActivity(env, user, "account_self_delete", userName);
  await notifyAdmins(env);
  await notifySupport(env);

  return new Response(JSON.stringify({ ok: true }), {
    status: 200,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Set-Cookie": clearSessionCookie(),
    },
  });
}

async function getAvatarResponse(env, userId) {
  const target = await env.DB.prepare("SELECT avatar_data, avatar_version FROM users WHERE id = ?1")
    .bind(userId)
    .first();
  if (!target) return new Response("Not found", { status: 404 });
  const r2Key = `avatars/${userId}`;
  let obj = await env.FILES_BUCKET.get(r2Key);
  if (!obj && target.avatar_data) {
    // Lazy-Migration: alte Base64-Avatare beim ersten Abruf nach R2 uebertragen.
    const match = target.avatar_data.match(/^data:([^;]+);base64,(.+)$/);
    if (match) {
      const mime = match[1];
      const bytes = Uint8Array.from(atob(match[2]), (c) => c.charCodeAt(0));
      await env.FILES_BUCKET.put(r2Key, bytes, { httpMetadata: { contentType: mime } });
      obj = await env.FILES_BUCKET.get(r2Key);
    }
  }
  if (!obj) return new Response("Not found", { status: 404 });
  const headers = new Headers();
  headers.set("Content-Type", (obj.httpMetadata && obj.httpMetadata.contentType) || "image/jpeg");
  headers.set("Cache-Control", "public, max-age=31536000, immutable");
  return new Response(obj.body, { headers });
}

