async function handleChangePassword(request, env, user) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungueltige Anfrage." }, 400);
  }
  const currentPassword = body.currentPassword || "";
  const newPassword = body.newPassword || "";

  if (!currentPassword || !newPassword) {
    return json({ error: "Bitte fülle beide Passwortfelder aus." }, 400);
  }
  if (newPassword.length < 6) {
    return json({ error: "Das neue Passwort muss mindestens 6 Zeichen lang sein." }, 400);
  }

  const { hash: currentHash } = await hashPassword(currentPassword, user.password_salt);
  if (!timingSafeEqual(currentHash, user.password_hash)) {
    return json({ error: "Das aktuelle Passwort ist falsch." }, 403);
  }

  const { hash, salt } = await hashPassword(newPassword);
  await env.DB.prepare(
    "UPDATE users SET password_hash = ?1, password_salt = ?2, updated_at = datetime('now') WHERE id = ?3"
  )
    .bind(hash, salt, user.id)
    .run();

  // Alle anderen Sitzungen dieses Nutzers beenden (auf anderen Geräten ausloggen),
  // die aktuelle Sitzung bleibt aktiv, damit man nicht direkt selbst ausgeloggt wird.
  const cookies = parseCookies(request);
  const currentToken = cookies["session"];
  if (currentToken) {
    await env.DB.prepare("DELETE FROM sessions WHERE user_id = ?1 AND token != ?2")
      .bind(user.id, currentToken)
      .run();
  } else {
    await env.DB.prepare("DELETE FROM sessions WHERE user_id = ?1").bind(user.id).run();
  }
  await logActivity(env, user, "password_change", null);

  return json({ ok: true });
}

