async function setTicketStatus(request, env, ticketId, user) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungueltige Anfrage." }, 400);
  }
  if (!["open", "in_progress", "closed"].includes(body.status)) {
    return json({ error: "Ungueltiger Status." }, 400);
  }
  if (!isStaff(user)) {
    const ticket = await env.DB.prepare("SELECT created_by FROM tickets WHERE id = ?1").bind(ticketId).first();
    if (!ticket || ticket.created_by !== user.id) {
      return json({ error: "Kein Zugriff auf dieses Ticket." }, 403);
    }
    if (body.status !== "closed") {
      return json({ error: "Du kannst dein Ticket nur schliessen." }, 403);
    }
  }
  await env.DB.prepare("UPDATE tickets SET status = ?1, updated_at = datetime('now') WHERE id = ?2")
    .bind(body.status, ticketId)
    .run();
  await logActivity(env, user, "ticket_status_change", `#${ticketId} → ${body.status}`);
  await notifySupport(env);
  return json({ ok: true });
}

