async function deleteTicket(env, ticketId, user) {
  const ticket = await env.DB.prepare("SELECT created_by, subject FROM tickets WHERE id = ?1").bind(ticketId).first();
  if (!ticket) return json({ error: "Ticket nicht gefunden." }, 404);
  const isOwner = ticket.created_by === user.id;
  const isAdmin = user.role === "admin";
  if (!isAdmin && !isOwner) {
    return json({ error: "Kein Zugriff auf dieses Ticket." }, 403);
  }
  await env.DB.prepare("DELETE FROM ticket_messages WHERE ticket_id = ?1").bind(ticketId).run();
  await env.DB.prepare("DELETE FROM tickets WHERE id = ?1").bind(ticketId).run();
  await logActivity(env, user, "ticket_delete", ticket.subject);
  await notifySupport(env);
  return json({ ok: true });
}

