// =====================================================================
// DATEIABLAGE (privater Speicher pro Nutzer, R2 + D1)
// =====================================================================
const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB pro Datei
const USER_STORAGE_QUOTA_BYTES = 500 * 1024 * 1024; // 500MB pro Nutzer -- bleibt weit unter dem 10GB-R2-Freikontingent

async function getFolderBreadcrumb(env, folderId) {
  const chain = [];
  let currentId = folderId;
  while (currentId) {
    const folder = await env.DB.prepare("SELECT id, name, parent_id FROM file_folders WHERE id = ?1").bind(currentId).first();
    if (!folder) break;
    chain.unshift({ id: folder.id, name: folder.name });
    currentId = folder.parent_id;
  }
  return chain;
}

async function getUserStorageUsage(env, userId) {
  const row = await env.DB.prepare("SELECT COALESCE(SUM(size), 0) AS total FROM file_items WHERE user_id = ?1")
    .bind(userId)
    .first();
  return (row && row.total) || 0;
}

async function listFilesFolder(request, env, user) {
  const url = new URL(request.url);
  const folderIdParam = url.searchParams.get("folderId");
  const folderId = folderIdParam ? Number(folderIdParam) : null;

  if (folderId) {
    const folder = await env.DB.prepare("SELECT id, user_id FROM file_folders WHERE id = ?1").bind(folderId).first();
    if (!folder || folder.user_id !== user.id) {
      return json({ error: "Ordner nicht gefunden." }, 404);
    }
  }

  const { results: folders } = await env.DB.prepare(
    "SELECT id, name, created_at FROM file_folders WHERE user_id = ?1 AND parent_id IS ?2 ORDER BY name ASC"
  ).bind(user.id, folderId).all();

  const { results: files } = await env.DB.prepare(
    "SELECT id, filename, size, mime_type, created_at FROM file_items WHERE user_id = ?1 AND folder_id IS ?2 ORDER BY filename ASC"
  ).bind(user.id, folderId).all();

  const breadcrumb = folderId ? await getFolderBreadcrumb(env, folderId) : [];
  const used = await getUserStorageUsage(env, user.id);

  return json({ folders, files, breadcrumb, folderId, usage: { used, quota: USER_STORAGE_QUOTA_BYTES } });
}

async function createFileFolder(request, env, user) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungueltige Anfrage." }, 400);
  }
  const name = (body.name || "").trim();
  if (!name) return json({ error: "Name darf nicht leer sein." }, 400);
  if (name.length > 100) return json({ error: "Name ist zu lang (max. 100 Zeichen)." }, 400);

  let parentId = body.parentId ? Number(body.parentId) : null;
  if (parentId) {
    const parent = await env.DB.prepare("SELECT user_id FROM file_folders WHERE id = ?1").bind(parentId).first();
    if (!parent || parent.user_id !== user.id) {
      return json({ error: "Uebergeordneter Ordner nicht gefunden." }, 404);
    }
  }

  const result = await env.DB.prepare(
    "INSERT INTO file_folders (user_id, parent_id, name) VALUES (?1, ?2, ?3)"
  ).bind(user.id, parentId, name).run();
  const folder = await env.DB.prepare("SELECT * FROM file_folders WHERE id = ?1")
    .bind(result.meta.last_row_id)
    .first();

  await logActivity(env, user, "folder_create", name);
  return json({ folder });
}

async function deleteFileFolder(env, folderId, user) {
  const folder = await env.DB.prepare("SELECT user_id, name FROM file_folders WHERE id = ?1").bind(folderId).first();
  if (!folder) return json({ error: "Ordner nicht gefunden." }, 404);
  if (folder.user_id !== user.id) return json({ error: "Kein Zugriff auf diesen Ordner." }, 403);

  const { results: descendants } = await env.DB.prepare(
    `WITH RECURSIVE descendants(id) AS (
       SELECT id FROM file_folders WHERE id = ?1
       UNION ALL
       SELECT f.id FROM file_folders f JOIN descendants d ON f.parent_id = d.id
     )
     SELECT id FROM descendants`
  ).bind(folderId).all();
  const folderIds = descendants.map((d) => d.id);
  const placeholders = folderIds.map((_, i) => `?${i + 1}`).join(",");

  const { results: filesToDelete } = await env.DB.prepare(
    `SELECT id, r2_key FROM file_items WHERE folder_id IN (${placeholders})`
  ).bind(...folderIds).all();

  if (filesToDelete.length) {
    await env.FILES_BUCKET.delete(filesToDelete.map((f) => f.r2_key));
    await env.DB.prepare(`DELETE FROM file_items WHERE folder_id IN (${placeholders})`).bind(...folderIds).run();
  }
  await env.DB.prepare(`DELETE FROM file_folders WHERE id IN (${placeholders})`).bind(...folderIds).run();

  await logActivity(env, user, "folder_delete", folder.name);
  return json({ ok: true });
}

async function uploadFileItem(request, env, user) {
  let form;
  try {
    form = await request.formData();
  } catch {
    return json({ error: "Ungueltige Anfrage." }, 400);
  }
  const file = form.get("file");
  if (!file || typeof file === "string") {
    return json({ error: "Keine Datei erhalten." }, 400);
  }
  if (file.size > MAX_FILE_SIZE) {
    return json({ error: "Datei ist zu gross (max. 50MB pro Datei)." }, 413);
  }

  const used = await getUserStorageUsage(env, user.id);
  if (used + file.size > USER_STORAGE_QUOTA_BYTES) {
    const freeBytes = Math.max(0, USER_STORAGE_QUOTA_BYTES - used);
    const freeMb = (freeBytes / (1024 * 1024)).toFixed(1);
    return json({ error: `Speicherlimit erreicht. Noch verfuegbar: ${freeMb}MB von 500MB.` }, 413);
  }

  const folderIdRaw = form.get("folderId");
  let folderId = folderIdRaw ? Number(folderIdRaw) : null;
  if (folderId) {
    const folder = await env.DB.prepare("SELECT user_id FROM file_folders WHERE id = ?1").bind(folderId).first();
    if (!folder || folder.user_id !== user.id) return json({ error: "Ordner nicht gefunden." }, 404);
  }

  const safeName = file.name.replace(/[\/\\]/g, "_").slice(0, 200);
  const r2Key = `files/${user.id}/${crypto.randomUUID()}-${safeName}`;

  await env.FILES_BUCKET.put(r2Key, file.stream(), {
    httpMetadata: { contentType: file.type || "application/octet-stream" },
  });

  const result = await env.DB.prepare(
    "INSERT INTO file_items (user_id, folder_id, filename, r2_key, size, mime_type) VALUES (?1, ?2, ?3, ?4, ?5, ?6)"
  ).bind(user.id, folderId, file.name.slice(0, 200), r2Key, file.size, file.type || null).run();

  const item = await env.DB.prepare(
    "SELECT id, filename, size, mime_type, created_at FROM file_items WHERE id = ?1"
  ).bind(result.meta.last_row_id).first();

  await logActivity(env, user, "file_upload", file.name);
  return json({ file: item });
}

async function downloadFileItem(env, fileId, user) {
  const item = await env.DB.prepare("SELECT * FROM file_items WHERE id = ?1").bind(fileId).first();
  if (!item) return new Response("Not found", { status: 404 });
  if (item.user_id !== user.id) return new Response("Forbidden", { status: 403 });
  const obj = await env.FILES_BUCKET.get(item.r2_key);
  if (!obj) return new Response("Not found", { status: 404 });
  const headers = new Headers();
  headers.set("Content-Type", item.mime_type || "application/octet-stream");
  headers.set("Content-Disposition", `attachment; filename="${item.filename.replace(/"/g, "")}"`);
  headers.set("Content-Length", String(item.size));
  headers.set("X-Content-Type-Options", "nosniff");
  return new Response(obj.body, { headers });
}

function isViewableMime(mime) {
  if (!mime) return false;
  // SVG kann Skripte enthalten -- bewusst nicht inline anzeigen (XSS-Risiko).
  if (mime === "image/svg+xml") return false;
  if (mime.startsWith("image/")) return true;
  if (mime === "application/pdf") return true;
  if (mime.startsWith("audio/")) return true;
  if (mime.startsWith("video/")) return true;
  if (mime === "text/plain" || mime === "text/csv" || mime === "text/markdown") return true;
  return false;
}

async function viewFileItem(env, fileId, user) {
  const item = await env.DB.prepare("SELECT * FROM file_items WHERE id = ?1").bind(fileId).first();
  if (!item) return new Response("Not found", { status: 404 });
  if (item.user_id !== user.id) return new Response("Forbidden", { status: 403 });
  if (!isViewableMime(item.mime_type)) {
    return new Response("Dieser Dateityp kann nicht im Browser geoeffnet werden.", { status: 415 });
  }
  const obj = await env.FILES_BUCKET.get(item.r2_key);
  if (!obj) return new Response("Not found", { status: 404 });
  const headers = new Headers();
  headers.set("Content-Type", item.mime_type || "application/octet-stream");
  headers.set("Content-Disposition", `inline; filename="${item.filename.replace(/"/g, "")}"`);
  headers.set("X-Content-Type-Options", "nosniff");
  return new Response(obj.body, { headers });
}

