async function updateProjectCard(request, env, cardId, user) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungueltige Anfrage." }, 400);
  }
  const card = await env.DB.prepare("SELECT * FROM project_cards WHERE id = ?1").bind(cardId).first();
  if (!card) return json({ error: "Karte nicht gefunden." }, 404);

  const fields = [];
  const values = [];
  let i = 1;

  if (body.title !== undefined) {
    const title = String(body.title).trim();
    if (!title) return json({ error: "Titel darf nicht leer sein." }, 400);
    fields.push(`title = ?${i++}`); values.push(title.slice(0, 200));
  }
  if (body.description !== undefined) {
    fields.push(`description = ?${i++}`); values.push(String(body.description).slice(0, 5000) || null);
  }
  if (body.assignedTo !== undefined) {
    fields.push(`assigned_to = ?${i++}`); values.push(body.assignedTo ? Number(body.assignedTo) : null);
  }
  if (body.dueDate !== undefined) {
    fields.push(`due_date = ?${i++}`); values.push(body.dueDate || null);
  }
  if (body.columnId !== undefined) {
    const newColId = Number(body.columnId);
    const col = await env.DB.prepare("SELECT id FROM project_columns WHERE id = ?1 AND board_id = ?2").bind(newColId, card.board_id).first();
    if (!col) return json({ error: "Spalte nicht gefunden." }, 404);
    const maxPos = await env.DB.prepare(
      "SELECT COALESCE(MAX(position), -1) AS maxPos FROM project_cards WHERE column_id = ?1"
    ).bind(newColId).first();
    fields.push(`column_id = ?${i++}`); values.push(newColId);
    fields.push(`position = ?${i++}`); values.push(maxPos.maxPos + 1);
  }

  if (fields.length === 0) return json({ ok: true });

  fields.push(`updated_at = datetime('now')`);
  values.push(cardId);
  await env.DB.prepare(`UPDATE project_cards SET ${fields.join(", ")} WHERE id = ?${i}`).bind(...values).run();

  await logActivity(env, user, "card_update", card.title);
  return json({ ok: true });
}

