// =====================================================================
// HUB-VORSCHAU (Satelliten-Blasen beim Hover/Long-Press auf App-Icons)
// =====================================================================

// Merkt sich pro Nutzer und App, wann zuletzt "alles gesehen" wurde.
// Die Tabelle wird beim ersten Zugriff automatisch angelegt -- keine manuelle Migration noetig.
let appSeenTableReady = false;
async function ensureAppSeenTable(env) {
  if (appSeenTableReady) return;
  await env.DB.prepare(
    `CREATE TABLE IF NOT EXISTS app_seen (
       user_id INTEGER NOT NULL,
       app_id TEXT NOT NULL,
       seen_at TEXT NOT NULL,
       PRIMARY KEY (user_id, app_id)
     )`
  ).run();
  appSeenTableReady = true;
}

const SEEN_APPS = ["todo", "support", "news", "projects", "files"];

// Fehlende Zeilen werden mit "jetzt" angelegt: wer eine App noch nie geoeffnet hat,
// startet mit einem sauberen Stand statt mit hunderten alten Eintraegen im Badge.
async function getSeenMap(env, userId) {
  await ensureAppSeenTable(env);
  try {
    await env.DB.batch(
      SEEN_APPS.map((appId) =>
        env.DB.prepare(
          "INSERT OR IGNORE INTO app_seen (user_id, app_id, seen_at) VALUES (?1, ?2, datetime('now'))"
        ).bind(userId, appId)
      )
    );
  } catch (err) {
    // Anlegen der fehlenden Zeilen ist Komfort -- vorhandene Staende trotzdem lesen.
    console.log("app_seen initialisieren fehlgeschlagen:", err);
  }
  const { results } = await env.DB.prepare(
    "SELECT app_id, seen_at FROM app_seen WHERE user_id = ?1"
  ).bind(userId).all();
  const map = {};
  for (const row of results) map[row.app_id] = row.seen_at;
  return map;
}

async function markAppSeen(env, userId, appId) {
  if (!SEEN_APPS.includes(appId)) return;
  try {
    await ensureAppSeenTable(env);
    await env.DB.prepare(
      `INSERT INTO app_seen (user_id, app_id, seen_at) VALUES (?1, ?2, datetime('now'))
       ON CONFLICT(user_id, app_id) DO UPDATE SET seen_at = datetime('now')`
    ).bind(userId, appId).run();
  } catch (err) {
    // Der "gesehen"-Stempel ist reine Komfortfunktion -- ein Fehler darf die App nie blockieren.
    console.log("markAppSeen fehlgeschlagen:", err);
  }
}

// SQLite-Zeitstempel ("YYYY-MM-DD HH:MM:SS", UTC) sicher nach Date wandeln.
function parseSqlTime(value) {
  if (!value) return null;
  const iso = String(value).includes("T") ? String(value) : String(value).replace(" ", "T") + "Z";
  const d = new Date(iso);
  return isNaN(d.getTime()) ? null : d;
}

async function getHubPreview(env, user) {
  const seen = await getSeenMap(env, user.id).catch(() => ({}));
  const displayName = user.vorname + " " + user.nachname;
  const staff = isStaff(user);

  // ---- To-Do: neue Aufgaben von anderen aus der Durable Object ----
  let todo = { items: [], count: 0 };
  try {
    const id = env.TODO_ROOM.idFromName("main-room");
    const stub = env.TODO_ROOM.get(id);
    const res = await stub.fetch("https://internal/preview");
    if (res.ok) {
      const data = await res.json();
      const since = parseSqlTime(seen.todo);
      const isFresh = (createdBy, createdAt) => {
        if (createdBy === displayName) return false;
        // Ohne bekannten "gesehen"-Stand lieber nichts melden, statt die ganze Historie.
        if (!since) return false;
        const created = parseSqlTime(createdAt);
        return created ? created > since : false;
      };

      // Neue Unteraufgaben zaehlen mit, tauchen in der Vorschau aber nur ueber
      // ihre Hauptaufgabe auf -- dort steht dann immer der Titel der Hauptaufgabe.
      let count = 0;
      const touched = [];
      for (const t of data.tasks || []) {
        const taskIsNew = isFresh(t.createdBy, t.createdAt);
        const freshSubtasks = (t.subtasks || []).filter((s) => isFresh(s.createdBy, s.createdAt));
        const hits = (taskIsNew ? 1 : 0) + freshSubtasks.length;
        if (hits === 0) continue;
        count += hits;
        const stamps = [taskIsNew ? parseSqlTime(t.createdAt) : null, ...freshSubtasks.map((s) => parseSqlTime(s.createdAt))].filter(Boolean);
        touched.push({ id: t.id, title: t.title, latest: stamps.reduce((a, b) => (a > b ? a : b)) });
      }
      touched.sort((a, b) => b.latest - a.latest);
      todo.count = count;
      todo.items = touched.slice(0, 3).map((t) => ({ id: t.id, title: t.title }));
    }
  } catch {
    // Vorschau ist rein informativ -- bei Fehlern einfach leer lassen.
  }

  // ---- Support: neue Tickets und neue Antworten von anderen ----
  let support = { items: [], count: 0 };
  try {
    const since = seen.support || null;

    // Neue Tickets von anderen gibt es nur fuer Staff -- normale Nutzer sehen ohnehin
    // ausschliesslich ihre eigenen Tickets, dort waere die Zahl immer 0.
    let newTicketCount = 0;
    if (staff) {
      const row = await env.DB.prepare(
        "SELECT COUNT(*) AS n FROM tickets WHERE created_at > ?1 AND created_by IS NOT ?2"
      ).bind(since, user.id).first();
      newTicketCount = (row && row.n) || 0;
    }

    const newMsgs = await env.DB.prepare(
      `SELECT COUNT(*) AS n FROM ticket_messages m JOIN tickets t ON t.id = m.ticket_id
       WHERE m.created_at > ?1 AND m.author_id IS NOT ?2${staff ? "" : " AND t.created_by = ?2"}`
    ).bind(since, user.id).first();

    support.count = newTicketCount + ((newMsgs && newMsgs.n) || 0);

    const { results } = await env.DB.prepare(
      `SELECT t.id, t.subject, t.priority FROM tickets t
       WHERE ( (t.created_at > ?1 AND t.created_by IS NOT ?2)
               OR EXISTS (SELECT 1 FROM ticket_messages m
                          WHERE m.ticket_id = t.id AND m.created_at > ?1 AND m.author_id IS NOT ?2) )
         AND t.status != 'closed'${staff ? "" : " AND t.created_by = ?2"}
       ORDER BY t.updated_at DESC LIMIT 3`
    ).bind(since, user.id).all();
    support.items = results || [];
  } catch (err) {
    console.log("Support-Vorschau fehlgeschlagen:", err);
  }

  // ---- News: neue Beitraege von anderen ----
  let news = { items: [], count: 0 };
  try {
    const since = seen.news || null;
    const row = await env.DB.prepare(
      "SELECT COUNT(*) AS n FROM news WHERE created_at > ?1 AND author_id IS NOT ?2"
    ).bind(since, user.id).first();
    news.count = (row && row.n) || 0;
    const { results } = await env.DB.prepare(
      `SELECT id, title, category FROM news
       WHERE created_at > ?1 AND author_id IS NOT ?2
       ORDER BY created_at DESC, id DESC LIMIT 3`
    ).bind(since, user.id).all();
    news.items = results || [];
  } catch (err) {
    console.log("News-Vorschau fehlgeschlagen:", err);
  }

  // ---- Projekte: neue Boards UND neue Karten von anderen ----
  let projects = { items: [], count: 0 };
  try {
    const since = seen.projects || null;

    const newBoardsCount = await env.DB.prepare(
      "SELECT COUNT(*) AS n FROM project_boards WHERE created_at > ?1 AND created_by IS NOT ?2"
    ).bind(since, user.id).first();
    const newCardsCount = await env.DB.prepare(
      "SELECT COUNT(*) AS n FROM project_cards WHERE created_at > ?1 AND created_by IS NOT ?2"
    ).bind(since, user.id).first();
    projects.count = ((newBoardsCount && newBoardsCount.n) || 0) + ((newCardsCount && newCardsCount.n) || 0);

    const { results: newBoards } = await env.DB.prepare(
      `SELECT id, name AS title, created_at FROM project_boards
       WHERE created_at > ?1 AND created_by IS NOT ?2
       ORDER BY created_at DESC LIMIT 3`
    ).bind(since, user.id).all();
    const { results: newCards } = await env.DB.prepare(
      `SELECT c.id, c.title, b.name AS board_name, c.created_at FROM project_cards c
       JOIN project_columns col ON col.id = c.column_id
       JOIN project_boards b ON b.id = col.board_id
       WHERE c.created_at > ?1 AND c.created_by IS NOT ?2
       ORDER BY c.created_at DESC LIMIT 3`
    ).bind(since, user.id).all();

    const combined = [
      ...(newBoards || []).map((b) => ({ id: b.id, title: b.title, is_board: true, created_at: b.created_at })),
      ...(newCards || []).map((c) => ({ id: c.id, title: c.title, board_name: c.board_name, is_board: false, created_at: c.created_at })),
    ];
    combined.sort((a, b) => (a.created_at < b.created_at ? 1 : a.created_at > b.created_at ? -1 : 0));
    projects.items = combined.slice(0, 3);
  } catch (err) {
    console.log("Projekt-Vorschau fehlgeschlagen:", err);
  }

  // ---- Dateien: bleiben ohne Zaehler (Dateien sind privat, es gibt nichts "von anderen") ----
  let files = { items: [], count: 0 };
  try {
    const { results } = await env.DB.prepare(
      "SELECT id, filename, size FROM file_items WHERE user_id = ?1 ORDER BY created_at DESC LIMIT 3"
    ).bind(user.id).all();
    files.items = results || [];
  } catch {
    // optional
  }

  // ---- Admin: offene Registrierungen, die freigeschaltet werden wollen ----
  let admin = { items: [], count: 0 };
  if (user.role === "admin") {
    try {
      const row = await env.DB.prepare(
        "SELECT COUNT(*) AS n FROM users WHERE status = 'pending'"
      ).first();
      admin.count = (row && row.n) || 0;
      const { results } = await env.DB.prepare(
        `SELECT id, vorname, nachname FROM users WHERE status = 'pending'
         ORDER BY created_at ASC LIMIT 3`
      ).all();
      admin.items = results || [];
    } catch (err) {
      console.log("Admin-Vorschau fehlgeschlagen:", err);
    }
  }

  return json({ todo, support, news, projects, files, admin });
}

// =====================================================================
// ROUTER
// =====================================================================
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // ---- Marken-Assets (oeffentlich, ohne Login) ----
    if (path === "/assets/byteliebe-logo-dark.png") return binResponse(LOGO_DARK_PNG_B64, "image/png");
    if (path === "/assets/byteliebe-logo-light.png") return binResponse(LOGO_LIGHT_PNG_B64, "image/png");
    if (path === "/favicon.svg") return binResponse(FAVICON_SVG_B64, "image/svg+xml");
    if (path === "/favicon-32.png" || path === "/favicon.ico") return binResponse(FAVICON_32_B64, "image/png");
    if (path === "/favicon-16.png") return binResponse(FAVICON_16_B64, "image/png");
    if (path === "/apple-touch-icon.png" || path === "/apple-touch-icon-precomposed.png") return binResponse(APPLE_TOUCH_B64, "image/png");

    // ---- Öffentliche Auth-Routen ----
    if (path === "/auth/register" && request.method === "POST") return handleRegister(request, env);
    if (path === "/auth/login" && request.method === "POST") return handleLogin(request, env);
    if (path === "/auth/logout" && request.method === "POST") return handleLogout(request, env);
    if (path === "/auth/forgot-password" && request.method === "POST") return handleForgotPassword(request, env);
    if (path === "/auth/reset-password" && request.method === "POST") return handleResetPassword(request, env);
    if (path === "/login.html" || path === "/login") return htmlResponse(LOGIN_HTML);
    if (path === "/login.js") return jsResponse(LOGIN_JS);
    if (path === "/reset-password.html" || path === "/reset-password") return htmlResponse(RESET_HTML);

    const user = await getSessionUser(request, env);

    // ---- Admin-Bereich ----
    if (path.startsWith("/admin")) {
      if (!user) return Response.redirect(PUBLIC_BASE_URL + "/login.html", 302);
      if (user.role !== "admin" || user.status !== "approved") {
        return new Response("Forbidden", { status: 403 });
      }
      if (path === "/admin" || path === "/admin/") return htmlResponse(buildAdminHtml(user));
      if (path === "/admin.js") return jsResponse(ADMIN_JS);
      if (path === "/admin/ws") {
        const upgradeHeader = request.headers.get("Upgrade");
        if (!upgradeHeader || upgradeHeader !== "websocket") {
          return new Response("Erwarte Upgrade: websocket", { status: 426 });
        }
        const adminRoomId = env.TODO_ROOM.idFromName("admin-room");
        const adminStub = env.TODO_ROOM.get(adminRoomId);
        return adminStub.fetch(request);
      }
      if (path === "/admin/api/pending" && request.method === "GET") return json(await adminListPending(env));
      if (path === "/admin/api/users" && request.method === "GET") return json(await adminListAll(env));
      if (path === "/admin/api/approve" && request.method === "POST") return adminSetStatus(env, request, "approved", user);
      if (path === "/admin/api/reject" && request.method === "POST") return adminSetStatus(env, request, "rejected", user);
      if (path === "/admin/api/suspend" && request.method === "POST") return adminSetStatus(env, request, "suspended", user);
      if (path === "/admin/api/unsuspend" && request.method === "POST") return adminSetStatus(env, request, "approved", user);
      if (path === "/admin/api/setrole" && request.method === "POST") return adminSetRole(env, request, user);
      if (path === "/admin/api/delete" && request.method === "POST") return adminDeleteUser(env, request, user);
      if (path === "/admin/api/trigger-reset" && request.method === "POST") return adminTriggerReset(env, request, user);
      if (path === "/admin/api/activity" && request.method === "GET") return adminListActivity(env);
      {
        const m = path.match(/^\/admin\/api\/users\/(\d+)$/);
        if (m && request.method === "GET") return adminGetUserDetail(env, Number(m[1]));
      }
      return new Response("Not found", { status: 404 });
    }

    if (path === "/api/hub/preview" && request.method === "GET") {
      if (!user) return json({ error: "Nicht angemeldet." }, 401);
      return getHubPreview(env, user);
    }

    // ---- Startseite: Login als Overlay über geblurrter Apps-Ansicht, falls nicht eingeloggt ----
    if (path === "/" || path === "/index.html") {
      if (!user || user.status !== "approved") {
        return htmlResponse(GUEST_HOME_HTML);
      }
      return htmlResponse(buildHubHtml(user));
    }

    // ---- Geschützte App-Routen ----
    if (!user || user.status !== "approved") {
      if (path === "/ws") return new Response("Unauthorized", { status: 401 });
      return Response.redirect(PUBLIC_BASE_URL + "/login.html", 302);
    }

    if (path === "/ws") {
      const upgradeHeader = request.headers.get("Upgrade");
      if (!upgradeHeader || upgradeHeader !== "websocket") {
        return new Response("Erwarte Upgrade: websocket", { status: 426 });
      }
      const id = env.TODO_ROOM.idFromName("main-room");
      const stub = env.TODO_ROOM.get(id);
      return stub.fetch(request);
    }

    if (path === "/hub.js") return jsResponse(HUB_JS);

    // Vom Client aus aufgerufen (z.B. bei "pageshow"), damit die Lesebestaetigung
    // auch bei Browser-Zurueck/Vorwaerts (bfcache) gesetzt wird -- dabei findet
    // naemlich keine neue Anfrage an den Server statt, der Seitenaufruf oben
    // in "/apps/..." wuerde also allein nicht ausreichen.
    {
      const m = path.match(/^\/api\/app-seen\/([a-z]+)$/);
      if (m && request.method === "POST") {
        if (!SEEN_APPS.includes(m[1])) return json({ error: "Unbekannte App." }, 400);
        await markAppSeen(env, user.id, m[1]);
        return json({ ok: true });
      }
    }

    if (path === "/profile/avatar" && request.method === "POST") {
      return handleAvatarUpload(request, env, user);
    }
    if (path === "/profile/avatar" && request.method === "DELETE") {
      return handleAvatarDelete(env, user);
    }
    {
      const m = path.match(/^\/avatar\/(\d+)$/);
      if (m && request.method === "GET") return getAvatarResponse(env, Number(m[1]));
    }
    if (path === "/api/profile" && request.method === "POST") {
      return handleUpdateProfile(request, env, user);
    }
    if (path === "/api/profile/password" && request.method === "POST") {
      return handleChangePassword(request, env, user);
    }
    if (path === "/api/profile/delete-account" && request.method === "POST") {
      return handleDeleteAccount(request, env, user);
    }
    if (path === "/profile.js") return jsResponse(PROFILE_JS);
    if (path === "/apps/profile" || path === "/apps/profile/") {
      return htmlResponse(buildProfileHtml(user));
    }

    if (path === "/support.js") return jsResponse(SUPPORT_JS);

    if (path === "/support/ws") {
      const upgradeHeader = request.headers.get("Upgrade");
      if (!upgradeHeader || upgradeHeader !== "websocket") {
        return new Response("Erwarte Upgrade: websocket", { status: 426 });
      }
      const supportRoomId = env.TODO_ROOM.idFromName("support-room");
      const supportStub = env.TODO_ROOM.get(supportRoomId);
      return supportStub.fetch(request);
    }

    if (path === "/support/api/staff" && request.method === "GET") {
      if (!isStaff(user)) return json({ error: "Forbidden" }, 403);
      return listStaff(env);
    }
    if (path === "/support/api/tickets" && request.method === "GET") {
      return listTickets(request, env, user);
    }
    if (path === "/support/api/tickets" && request.method === "POST") {
      return createTicket(request, env, user);
    }
    {
      const m = path.match(/^\/support\/api\/tickets\/(\d+)$/);
      if (m && request.method === "GET") return getTicket(env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/support\/api\/tickets\/(\d+)\/messages$/);
      if (m && request.method === "POST") return addTicketMessage(request, env, user, Number(m[1]));
    }
    {
      const m = path.match(/^\/support\/api\/tickets\/(\d+)\/status$/);
      if (m && request.method === "POST") return setTicketStatus(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/support\/api\/tickets\/(\d+)\/priority$/);
      if (m && request.method === "POST") return setTicketPriority(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/support\/api\/tickets\/(\d+)\/assign$/);
      if (m && request.method === "POST") return assignTicket(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/support\/api\/tickets\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteTicket(env, Number(m[1]), user);
    }

    if (path === "/apps/support" || path === "/apps/support/") {
      ctx.waitUntil(markAppSeen(env, user.id, "support"));
      return htmlResponse(buildSupportHtml(user));
    }

    if (path === "/news.js") return jsResponse(NEWS_JS);
    if (path === "/api/news" && request.method === "GET") return listNews(env);
    if (path === "/api/news" && request.method === "POST") return createNews(request, env, user);
    if (path === "/api/news/unseen" && request.method === "GET") return listUnseenNews(env, user);
    if (path === "/api/news/seen" && request.method === "POST") return markNewsSeen(env, user);
    {
      const m = path.match(/^\/api\/news\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteNews(env, Number(m[1]), user);
    }
    if (path === "/apps/news" || path === "/apps/news/") {
      ctx.waitUntil(markAppSeen(env, user.id, "news"));
      return htmlResponse(buildNewsHtml(user));
    }

    if (path === "/files.js") return jsResponse(FILES_JS);
    if (path === "/api/files" && request.method === "GET") return listFilesFolder(request, env, user);
    if (path === "/api/files/folder" && request.method === "POST") return createFileFolder(request, env, user);
    if (path === "/api/files/upload" && request.method === "POST") return uploadFileItem(request, env, user);
    {
      const m = path.match(/^\/api\/files\/download\/(\d+)$/);
      if (m && request.method === "GET") return downloadFileItem(env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/files\/folder\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteFileFolder(env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/files\/view\/(\d+)$/);
      if (m && request.method === "GET") return viewFileItem(env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/files\/folder\/(\d+)\/rename$/);
      if (m && request.method === "POST") return renameFileFolder(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/files\/(\d+)\/rename$/);
      if (m && request.method === "POST") return renameFileItem(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/files\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteFileItem(env, Number(m[1]), user);
    }
    if (path === "/apps/files" || path === "/apps/files/") {
      ctx.waitUntil(markAppSeen(env, user.id, "files"));
      return htmlResponse(buildFilesHtml(user));
    }

    if (path === "/api/team/members" && request.method === "GET") return listTeamMembers(env);

    if (path === "/projects.js") return jsResponse(PROJECTS_JS);
    if (path === "/api/projects" && request.method === "GET") return listProjectBoards(env);
    if (path === "/api/projects" && request.method === "POST") return createProjectBoard(request, env, user);
    {
      const m = path.match(/^\/api\/projects\/(\d+)$/);
      if (m && request.method === "GET") return getProjectBoardDetail(env, Number(m[1]));
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteProjectBoard(env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/columns$/);
      if (m && request.method === "POST") return createProjectColumn(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/columns\/(\d+)\/rename$/);
      if (m && request.method === "POST") return renameProjectColumn(request, env, Number(m[2]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/columns\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteProjectColumn(env, Number(m[2]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/cards$/);
      if (m && request.method === "POST") return createProjectCard(request, env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/cards\/(\d+)$/);
      if (m && request.method === "GET") return getProjectCardDetail(env, Number(m[2]));
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/cards\/(\d+)$/);
      if (m && request.method === "PATCH") return updateProjectCard(request, env, Number(m[2]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/cards\/(\d+)$/);
      if (m && request.method === "DELETE") return deleteProjectCard(env, Number(m[2]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/(\d+)\/cards\/(\d+)\/files$/);
      if (m && request.method === "POST") return attachFileToCard(request, env, Number(m[2]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/cards\/files\/(\d+)$/);
      if (m && request.method === "DELETE") return removeCardFile(env, Number(m[1]), user);
    }
    {
      const m = path.match(/^\/api\/projects\/cards\/files\/(\d+)\/view$/);
      if (m && request.method === "GET") return viewCardFile(env, Number(m[1]));
    }
    {
      const m = path.match(/^\/api\/projects\/cards\/files\/(\d+)\/download$/);
      if (m && request.method === "GET") return downloadCardFile(env, Number(m[1]));
    }
    if (path === "/apps/projects" || path === "/apps/projects/") {
      ctx.waitUntil(markAppSeen(env, user.id, "projects"));
      return htmlResponse(buildProjectsHtml(user));
    }

    if (path === "/apps/todo" || path === "/apps/todo/") {
      ctx.waitUntil(markAppSeen(env, user.id, "todo"));
      const displayName = user.vorname + " " + user.nachname;
      return htmlResponse(buildAppHtml(displayName, user.role === "admin"));
    }

    return new Response("Not found", { status: 404 });
  },
};


// ---- Durable Object: hält die Aufgabenliste & alle WebSocket-Verbindungen ----
export class TodoRoom extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.tasks = [];

    // Beim (Re-)Start der DO gespeicherte Aufgaben laden, bevor Requests bedient werden.
    ctx.blockConcurrencyWhile(async () => {
      this.tasks = (await this.ctx.storage.get("tasks")) || [];
    });
  }

  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/preview") {
      // Leichter Nur-Lese-Zugriff fuer die Hub-Vorschau (Satelliten-Blasen) --
      // keine WebSocket-Verbindung, rein additiv, beeinflusst den Live-Sync-Pfad nicht.
      return new Response(JSON.stringify({ tasks: this.tasks }), {
        headers: { "Content-Type": "application/json" },
      });
    }
    const webSocketPair = new WebSocketPair();
    const [client, server] = Object.values(webSocketPair);

    // Hibernatable WebSocket: die DO kann bei Inaktivität aus dem Speicher entfernt
    // werden, ohne dass die Verbindung getrennt wird.
    this.ctx.acceptWebSocket(server);

    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws, raw) {
    let msg;
    try {
      msg = JSON.parse(raw);
    } catch {
      return;
    }

    switch (msg.type) {
      case "hello": {
        // Neu verbundener Client bekommt den aktuellen Stand.
        ws.send(JSON.stringify({ type: "init", tasks: this.tasks }));
        break;
      }

      case "task:create": {
        if (!msg.title || !msg.title.trim()) return;
        const task = {
          id: crypto.randomUUID(),
          title: msg.title.trim(),
          note: msg.note || "",
          subtasks: [],
          createdBy: msg.user || "Unbekannt",
          createdAt: new Date().toISOString(),
        };
        this.tasks.push(task);
        await this.save();
        this.broadcast({ type: "task:created", task });
        break;
      }

      case "task:delete": {
        const idx = this.tasks.findIndex((t) => t.id === msg.taskId);
        if (idx === -1) return;
        this.tasks.splice(idx, 1);
        await this.save();
        this.broadcast({ type: "task:deleted", taskId: msg.taskId });
        break;
      }

      case "task:update": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        if (typeof msg.title === "string") task.title = msg.title;
        if (typeof msg.note === "string") task.note = msg.note;
        await this.save();
        this.broadcast({ type: "task:updated", task });
        break;
      }

      case "subtask:create": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task || !msg.title || !msg.title.trim()) return;
        const subtask = {
          id: crypto.randomUUID(),
          title: msg.title.trim(),
          done: false,
          doneBy: null,
          doneAt: null,
          createdBy: msg.user || "Unbekannt",
          createdAt: new Date().toISOString(),
        };
        task.subtasks.push(subtask);
        await this.save();
        this.broadcast({ type: "subtask:created", taskId: msg.taskId, subtask });
        break;
      }

      case "subtask:toggle": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        const sub = task.subtasks.find((s) => s.id === msg.subtaskId);
        if (!sub) return;
        sub.done = !sub.done;
        sub.doneBy = sub.done ? msg.user || "Unbekannt" : null;
        sub.doneAt = sub.done ? new Date().toISOString() : null;
        await this.save();
        this.broadcast({ type: "subtask:updated", taskId: msg.taskId, subtask: sub });
        break;
      }

      case "subtask:delete": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        task.subtasks = task.subtasks.filter((s) => s.id !== msg.subtaskId);
        await this.save();
        this.broadcast({ type: "subtask:deleted", taskId: msg.taskId, subtaskId: msg.subtaskId });
        break;
      }

      case "subtask:update": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        const sub = task.subtasks.find((s) => s.id === msg.subtaskId);
        if (!sub) return;
        if (typeof msg.title === "string") sub.title = msg.title;
        await this.save();
        this.broadcast({ type: "subtask:updated", taskId: msg.taskId, subtask: sub });
        break;
      }
    }
  }

  async webSocketClose(ws, code, reason, wasClean) {
    ws.close(code, reason);
  }

  async webSocketError(ws) {
    // Verbindung war fehlerhaft; nichts weiter zu tun, die Runtime räumt sie auf.
  }

  broadcast(msg) {
    const payload = JSON.stringify(msg);
    for (const ws of this.ctx.getWebSockets()) {
      try {
        ws.send(payload);
      } catch {
        // tote Verbindung ignorieren
      }
    }
  }

  // RPC-Methode: wird direkt vom Worker aufgerufen (kein WebSocket noetig),
  // um verbundene Clients (z.B. das Admin-Panel) sofort zu benachrichtigen.
  notify(msg) {
    this.broadcast(msg);
  }

  async save() {
    await this.ctx.storage.put("tasks", this.tasks);
  }
}
